cd $TMPDIR/q && python3 -I - <<'EOF'
import json,os
r=json.load(open(os.environ['TMPDIR']+'/q/rows2.json'))
print('block-util:')
for x in r:
    if x['how']=='block' and x['util']: print(x['y'],x['file'],x['page'],x['resp'][:80],'|',x['pen'])
print('empty resp:',[ (x['file'],x['page'],x['resp'][:40]) for x in r if not x['resp'].strip()][:20])
print('checkbox:')
for x in r:
    if 'Training or' in x['rec'] and x['rec'].startswith(('D ','M ','□','~','I(','K','0')) or x['rec'].startswith(('D Warning','□ ','D ','M ')): print(x['y'],x['file'],x['page'],x['resp'][:40],x['util'],x['pen'],x['rec'][:50])
EOF
